public static int Latency(int load, bool verbose) =>
    20 + 15 * (load - 1) + (verbose ? 10 * load : 0);

foreach (int load in new[] { 1, 2 })
foreach (bool verbose in new[] { false, true })
{
    int cost = LabExperiment.Latency(load, verbose);
    Console.WriteLine($"load={load} verbose={verbose} latency={cost} late={cost > 50}");
    Check((cost > 50) == (load == 2 && verbose),
        $"factorial_{load}_{verbose}");
}
